import { readFileSync } from 'node:fs'

const modes = ['merge', 'merge2', 'regions']
const args = process.argv.slice(2)
function fail(msg) {
  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}
if (args.length !== 1 || !modes.includes(args[0])) fail('usage: cli.js merge|merge2|regions')
const mode = args[0]

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
const docs = [[]]
for (const l of lines) {
  if (l === '%%%') docs.push([])
  else docs[docs.length - 1].push(l)
}
if (docs.length !== 3) fail('expected three parts separated by %%%')
const [mine, base, theirs] = docs

function diff(a, b) {
  const n = a.length, m = b.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = a[i] === b[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const changes = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => {
    if (i > bs || j > ss) changes.push({ bs, be: i, ss, se: j })
  }
  while (i < n && j < m) {
    if (a[i] === b[j]) {
      flush()
      i++; j++; bs = i; ss = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n; j = m
  flush()
  return changes
}

const all = [
  ...diff(base, mine).map(c => ({ ...c, side: 0 })),
  ...diff(base, theirs).map(c => ({ ...c, side: 1 })),
]
all.sort((x, y) => x.bs - y.bs || x.side - y.side)

const same = (x, y) => x.length === y.length && x.every((v, k) => v === y[k])
const sides = [mine, theirs]
const out = []
let conflict = false
let pos = 0
let k = 0
const emit = (kind, ls, extra) => {
  if (mode === 'regions') out.push(extra ?? `${kind} ${ls.length}`)
  else out.push(...ls)
}
while (k < all.length) {
  const rs = all[k].bs
  let re = all[k].be
  const group = [all[k++]]
  while (k < all.length && all[k].bs <= re) {
    re = Math.max(re, all[k].be)
    group.push(all[k++])
  }
  if (rs > pos) emit('stable', base.slice(pos, rs))
  pos = re
  if (group.length === 1) {
    const c = group[0]
    emit(c.side === 0 ? 'mine' : 'theirs', sides[c.side].slice(c.ss, c.se))
    continue
  }
  const baseLines = base.slice(rs, re)
  const rep = [0, 1].map(s => {
    const cs = group.filter(c => c.side === s)
    if (!cs.length) return baseLines
    const bmin = Math.min(...cs.map(c => c.bs)), bmax = Math.max(...cs.map(c => c.be))
    const smin = Math.min(...cs.map(c => c.ss)), smax = Math.max(...cs.map(c => c.se))
    return sides[s].slice(smin - (bmin - rs), smax + (re - bmax))
  })
  const [m, t] = rep
  if (same(m, t)) emit('both', m)
  else if (same(m, baseLines)) emit('theirs', t)
  else if (same(t, baseLines)) emit('mine', m)
  else {
    conflict = true
    if (mode === 'regions') out.push(`conflict mine=${m.length} base=${baseLines.length} theirs=${t.length}`)
    else {
      out.push('<<<<<<< mine', ...m)
      if (mode === 'merge') out.push('||||||| base', ...baseLines)
      out.push('=======', ...t, '>>>>>>> theirs')
    }
  }
}
if (pos < base.length) emit('stable', base.slice(pos))
process.stdout.write(out.map(l => l + '\n').join(''))
process.exit(conflict ? 1 : 0)
