{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const fail = (msg, code = 2) => {
  process.stderr.write(msg + '\n')
  process.exit(code)
}
const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'
const args = process.argv.slice(2)
let mode = args[0]
let workers = 0
if (mode === 'waves' || mode === 'explain') {
  if (args.length !== 1) fail(USAGE)
} else if (mode === 'pack') {
  if (args.length !== 2) fail(USAGE)
  if (!/^[1-9][0-9]*$/.test(args[1])) fail('error: workers must be a positive integer')
  workers = Number(args[1])
} else fail(USAGE)

let text = ''
try { text = readFileSync(0, 'utf8') } catch { text = '' }
const lines = text.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const NAME = /^[A-Za-z0-9_.-]+$/
const cost = new Map()
const deps = new Map() // name -> Set
const used = []
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const w = line.split(/\s+/)
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!NAME.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (cost.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    cost.set(w[1], BigInt(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    for (const x of w.slice(1)) if (!NAME.test(x)) fail(`error: line ${n}: invalid task name ${x}`)
    if (!deps.has(w[1])) deps.set(w[1], new Set())
    for (const d of w.slice(2)) deps.get(w[1]).add(d)
    used.push(...w.slice(1))
  } else fail(`error: line ${n}: unknown directive ${w[0]}`)
})
for (const x of used) if (!cost.has(x)) fail(`error: unknown task ${x}`)

const names = [...cost.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
const dl = new Map(names.map((x) => [x, [...(deps.get(x) || [])].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))]))

// cycle detection
{
  const state = new Map()
  const stack = []
  const dfs = (u) => {
    state.set(u, 1)
    stack.push(u)
    for (const v of dl.get(u)) {
      if (state.get(v) === 1) {
        const cyc = stack.slice(stack.indexOf(v)).concat(v)
        fail('error: cycle: ' + cyc.join(' -> '), 3)
      }
      if (!state.has(v)) dfs(v)
    }
    stack.pop()
    state.set(u, 2)
  }
  for (const x of names) if (!state.has(x)) dfs(x)
}

const start = new Map(), finish = new Map(), depth = new Map()
const calc = (u) => {
  if (finish.has(u)) return
  let s = 0n, d = 0
  for (const v of dl.get(u)) {
    calc(v)
    if (finish.get(v) > s) s = finish.get(v)
    d = Math.max(d, depth.get(v) + 1)
  }
  start.set(u, s); finish.set(u, s + cost.get(u)); depth.set(u, d)
}
names.forEach(calc)
let total = 0n
for (const x of names) if (finish.get(x) > total) total = finish.get(x)

let out = ''
if (mode === 'waves') {
  const ws = []
  for (const x of names) (ws[depth.get(x)] ||= []).push(x)
  ws.forEach((g, k) => { out += `wave ${k}: ${g.join(' ')}\n` })
  out += `total ${total}\n`
} else if (mode === 'explain') {
  for (const x of names) out += `${x} start=${start.get(x)} finish=${finish.get(x)} depth=${depth.get(x)}\n`
  out += `total ${total}\n`
} else {
  const rev = new Map(names.map((x) => [x, []]))
  for (const x of names) for (const v of dl.get(x)) rev.get(v).push(x)
  const prio = new Map()
  const pr = (u) => {
    if (prio.has(u)) return prio.get(u)
    let m = 0n
    for (const c of rev.get(u)) { const p = pr(c); if (p > m) m = p }
    prio.set(u, m + cost.get(u))
    return m + cost.get(u)
  }
  names.forEach(pr)
  const order = [...names].sort((a, b) => (prio.get(a) > prio.get(b) ? -1 : prio.get(a) < prio.get(b) ? 1 : a < b ? -1 : 1))
  const fin = new Map()
  const freeAt = Array(workers).fill(0n)
  const runs = Array.from({ length: workers }, () => [])
  let t = 0n, done = 0, mk = 0n
  while (done < names.length) {
    for (;;) {
      const wi = freeAt.findIndex((f) => f <= t)
      if (wi < 0) break
      const task = order.find((x) => !fin.has(x) && dl.get(x).every((d) => fin.has(d) && fin.get(d) <= t))
      if (!task) break
      const f = t + cost.get(task)
      fin.set(task, f)
      freeAt[wi] = f
      runs[wi].push(`${task}@${t}-${f}`)
      if (f > mk) mk = f
      done++
    }
    if (done >= names.length) break
    let next = null
    for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
    t = next
  }
  runs.forEach((r, i) => { out += `worker ${i}:${r.map((s) => ' ' + s).join('')}\n` })
  out += `makespan ${mk}\n`
}
process.stdout.write(out)
EOF
