export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const costs = new Map()
  const deps = new Map()
  const depUses = []
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const w = line.split(/\s+/)
    const N = i + 1
    if (w[0] === 'task') {
      if (w.length !== 3) throw err(`error: line ${N}: expected task <name> <cost>`)
      if (!NAME.test(w[1])) throw err(`error: line ${N}: invalid task name ${w[1]}`)
      if (!/^[0-9]+$/.test(w[2])) throw err(`error: line ${N}: cost must be a non-negative integer`)
      if (costs.has(w[1])) throw err(`error: line ${N}: task ${w[1]} is declared twice`)
      costs.set(w[1], BigInt(w[2]))
    } else if (w[0] === 'dep') {
      if (w.length < 3) throw err(`error: line ${N}: expected dep <name> <dependency>...`)
      if (!deps.has(w[1])) deps.set(w[1], new Set())
      for (const d of w.slice(1)) depUses.push(d)
      for (const d of w.slice(2)) deps.get(w[1]).add(d)
    } else {
      throw err(`error: line ${N}: unknown directive ${w[0]}`)
    }
  })
  for (const n of depUses) if (!costs.has(n)) throw err(`error: unknown task ${n}`)
  const sorted = new Map()
  for (const n of costs.keys()) sorted.set(n, [...(deps.get(n) ?? [])].sort())
  return { costs, deps: sorted }
}

export function findCycle({ costs, deps }) {
  const state = new Map()
  for (const root of [...costs.keys()].sort()) {
    if (state.has(root)) continue
    const stack = [root]
    const idx = [0]
    state.set(root, 1)
    while (stack.length) {
      const top = stack[stack.length - 1]
      const ds = deps.get(top)
      const i = idx[idx.length - 1]
      if (i >= ds.length) {
        state.set(top, 2)
        stack.pop()
        idx.pop()
        continue
      }
      idx[idx.length - 1]++
      const d = ds[i]
      const s = state.get(d)
      if (s === 1) return [...stack.slice(stack.indexOf(d)), d]
      if (!s) {
        state.set(d, 1)
        stack.push(d)
        idx.push(0)
      }
    }
  }
  return null
}

export function schedule({ costs, deps }, names) {
  const start = new Map()
  const finish = new Map()
  const depth = new Map()
  let total = 0n
  const visit = (root) => {
    const stack = [root]
    while (stack.length) {
      const n = stack[stack.length - 1]
      if (finish.has(n)) {
        stack.pop()
        continue
      }
      const pending = deps.get(n).filter((d) => !finish.has(d))
      if (pending.length) {
        stack.push(...pending)
        continue
      }
      let s = 0n
      let dp = 0
