/** Runs the instant-runoff count; returns `{ rounds, winner }`. */
export function count({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const history = new Map(candidates.map((c) => [c, []]))
  const rounds = []
  let total = 0n
  for (const b of ballots) total += b.count
  for (;;) {
    const votes = new Map([...continuing].map((c) => [c, 0n]))
    let active = 0n
    for (const b of ballots) {
      const pick = b.ranking.find((c) => continuing.has(c))
      if (pick !== undefined) {
        votes.set(pick, votes.get(pick) + b.count)
        active += b.count
      }
    }
    for (const [c, v] of votes) history.get(c).push(v)
    const entries = [...votes].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
    const round = {
      entries: entries.map(([n, v]) => [n, v.toString()]),
      exhausted: (total - active).toString(),
      eliminated: null,
    }
    rounds.push(round)
    if (active === 0n) return { rounds, winner: null }
    const top = entries[0]
    if (top[1] * 2n > active) return { rounds, winner: top[0] }
    let tied = [...continuing]
    for (let r = 0; r < rounds.length && tied.length > 1; r++) {
      const min = tied.reduce((m, c) => (history.get(c)[r] < m ? history.get(c)[r] : m), history.get(tied[0])[r])
      tied = tied.filter((c) => history.get(c)[r] === min)
    }
    // `tied` now holds the lowest-ranked candidates: reduce to the fewest of this round first.
    round.eliminated = null
    const out = lowest(continuing, votes, history, rounds.length)
    round.eliminated = out
    continuing.delete(out)
  }
}

function lowest(continuing, votes, history, nRounds) {
  let min = null
  for (const v of votes.values()) if (min === null || v < min) min = v
  let tied = [...continuing].filter((c) => votes.get(c) === min)
  for (let r = 0; r < nRounds && tied.length > 1; r++) {
    let m = history.get(tied[0])[r]
    for (const c of tied) if (history.get(c)[r] < m) m = history.get(c)[r]
    tied = tied.filter((c) => history.get(c)[r] === m)
  }
  return tied.reduce((a, b) => (b > a ? b : a))
}
