{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */
import { readFileSync } from 'node:fs'

class Fail extends Error {}

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

const WORD = /^[A-Za-z0-9_./:-]+$/
const COUNT = /^(0|[1-9][0-9]*)$/

function count(text, field, least) {
  if (!COUNT.test(text) || BigInt(text) < BigInt(least)) {
    throw new Fail(`${field} must be an integer of at least ${least}`)
  }
  return BigInt(text)
}

function makeState(policy, tick) {
  if (policy.kind === 'bucket') {
    return { units: policy.capacity * policy.per, last: tick }
  }
  return { ticks: [] }
}

function advance(policy, st, tick) {
  if (policy.kind === 'bucket') {
    const dt = tick - st.last
    st.last = tick
    if (dt > 0n) {
      st.units += policy.refill * dt
      const max = policy.capacity * policy.per
      if (st.units > max) st.units = max
    }
  } else {
    const cut = tick - policy.span
    st.ticks = st.ticks.filter((t) => t > cut)
  }
}

function allows(policy, st) {
  return policy.kind === 'bucket' ? st.units >= policy.per : BigInt(st.ticks.length) < policy.limit
}

function record(policy, st, tick) {
  if (policy.kind === 'bucket') st.units -= policy.per
  else st.ticks.push(tick)
}

function main(input) {
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const states = new Map()
  const counts = new Map()
  const out = []
  let started = false
  let prev = null
  let allowed = 0
  let denied = 0

  for (let i = 0; i < lines.length; i++) {
    const text = lines[i].trim()
    if (text === '' || text.startsWith('#')) continue
    const f = text.split(/\s+/)
    const word = f[0]
    try {
      if (word === 'bucket' || word === 'window' || word === 'route') {
        if (started) throw new Fail('declarations must come before the first event')
      }
      if (word === 'bucket') {
        if (f.length !== 5) throw new Fail('expected bucket <name> <capacity> <refill> <per>')
        if (!WORD.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
        const capacity = count(f[2], 'capacity', 1)
        const refill = count(f[3], 'refill', 0)
        const per = count(f[4], 'per', 1)
        if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], { name: f[1], kind: 'bucket', capacity, refill, per })
      } else if (word === 'window') {
        if (f.length !== 4) throw new Fail('expected window <name> <limit> <span>')
        if (!WORD.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
        const limit = count(f[2], 'limit', 0)
        const span = count(f[3], 'span', 1)
        if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], { name: f[1], kind: 'window', limit, span })
      } else if (word === 'route') {
        if (f.length < 3) throw new Fail('expected route <prefix> <policy>...')
        if (!WORD.test(f[1])) throw new Fail(`invalid route prefix ${f[1]}`)
        if (routes.has(f[1])) throw new Fail(`prefix ${f[1]} is routed twice`)
        const list = []
        for (const n of f.slice(2)) {
          if (!policies.has(n)) throw new Fail(`unknown policy ${n}`)
          list.push(policies.get(n))
        }
        routes.set(f[1], list)
      } else if (word === 'event') {
        if (f.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = count(f[1], 'tick', 0)
        const key = f[2]
        if (!WORD.test(key)) throw new Fail(`invalid key ${key}`)
        if (prev !== null && tick < prev) throw new Fail(`tick ${tick} is before tick ${prev}`)
        started = true
        prev = tick
        let best = null
        for (const p of routes.keys()) {
          if (key.startsWith(p) && (best === null || p.length > best.length)) best = p
        }
        let refused = null
        if (best !== null) {
          const list = routes.get(best)
          const sts = list.map((p) => {
            const k = `${p.name}\0${key}`
            if (!states.has(k)) states.set(k, makeState(p, tick))
            return states.get(k)
          })
          list.forEach((p, j) => advance(p, sts[j], tick))
          for (let j = 0; j < list.length; j++) {
            if (!allows(list[j], sts[j])) { refused = list[j].name; break }
          }
          if (refused === null) list.forEach((p, j) => record(p, sts[j], tick))
        }
        const c = counts.get(key) || { a: 0, d: 0 }
        counts.set(key, c)
        if (refused === null) { c.a++; allowed++; out.push(`${tick} ${key} allow`) }
        else { c.d++; denied++; out.push(`${tick} ${key} deny ${refused}`) }
      } else {
        throw new Fail(`unknown directive ${word}`)
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  }

  if (mode === 'summary') {
    const keys = [...counts.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
    const res = keys.map((k) => `${k} allowed=${counts.get(k).a} denied=${counts.get(k).d}`)
    res.push(`total allowed=${allowed} denied=${denied}`)
    return res
  }
  return out
}

try {
  const lines = main(readFileSync(0, 'utf8'))
  process.stdout.write(lines.map((l) => l + '\n').join(''))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
"}

