function makeState(policy, tick) {
  if (policy.kind === 'bucket') {
    return { units: policy.capacity * policy.per, last: tick }
  }
  return { ticks: [] }
}

function advance(policy, st, tick) {
  if (policy.kind === 'bucket') {
    const dt = tick - st.last
    st.last = tick
    if (dt > 0n) {
      st.units += policy.refill * dt
      const max = policy.capacity * policy.per
      if (st.units > max) st.units = max
    }
  } else {
    const cut = tick - policy.span
    st.ticks = st.ticks.filter((t) => t > cut)
  }
}

function allows(policy, st) {
  return policy.kind === 'bucket' ? st.units >= policy.per : BigInt(st.ticks.length) < policy.limit
}

function record(policy, st, tick) {
  if (policy.kind === 'bucket') st.units -= policy.per
  else st.ticks.push(tick)
}

function main(input) {
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const states = new Map()
  const counts = new Map()
  const out = []
  let started = false
  let prev = null
  let allowed = 0
  let denied = 0

  for (let i = 0; i < lines.length; i++) {
    const text = lines[i].trim()
    if (text === '' || text.startsWith('#')) continue
    const f = text.split(/\s+/)
    const word = f[0]
    try {
      if (word === 'bucket' || word === 'window' || word === 'route') {
        if (started) throw new Fail('declarations must come before the first event')
      }
