import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_./:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

function int(field, text, least) {
  if (!INT.test(text) || BigInt(text) < BigInt(least)) {
    throw new Fail(`${field} must be an integer of at least ${least}`)
  }
  return BigInt(text)
}

class Bucket {
  constructor(name, cap, refill, per) { Object.assign(this, { name, cap, refill, per }); this.states = new Map() }
  state(key, tick) {
    let s = this.states.get(key)
    if (!s) { s = { tokens: this.cap * this.per, last: tick }; this.states.set(key, s) }
    return s
  }
  advance(key, tick) {
    const s = this.state(key, tick)
    const max = this.cap * this.per
    s.tokens += this.refill * (tick - s.last)
    if (s.tokens > max) s.tokens = max
    s.last = tick
  }
  allows(key) { return this.states.get(key).tokens >= this.per }
  record(key) { this.states.get(key).tokens -= this.per }
}

class Window {
  constructor(name, limit, span) { Object.assign(this, { name, limit, span }); this.states = new Map() }
  advance(key, tick) {
    let s = this.states.get(key)
    if (!s) { s = []; this.states.set(key, s) }
    const cut = tick - this.span
    let i = 0
    while (i < s.length && s[i] <= cut) i++
    if (i) s.splice(0, i)
  }
  allows(key) { return BigInt(this.states.get(key).length) < this.limit }
  record(key, tick) { this.states.get(key).push(tick) }
}

function run(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const out = []
  const stats = new Map()
  let started = false
  let prev = null
  for (let n = 0; n < lines.length; n++) {
    const line = lines[n].trim()
    if (line === '' || line.startsWith('#')) continue
    const f = line.split(/\s+/)
    try {
      const d = f[0]
      if (!['bucket', 'window', 'route', 'event'].includes(d)) throw new Fail(`unknown directive ${d}`)
      if (d !== 'event' && started) throw new Fail('declarations must come before the first event')
      if (d === 'bucket' || d === 'window') {
        const isB = d === 'bucket'
        if (f.length !== (isB ? 5 : 4)) {
          throw new Fail(isB ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>')
        }
        if (!NAME.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
        let p
        if (isB) p = new Bucket(f[1], int('capacity', f[2], 1), int('refill', f[3], 0), int('per', f[4], 1))
        else p = new Window(f[1], int('limit', f[2], 0), int('span', f[3], 1))
        if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], p)
      } else if (d === 'route') {
        if (f.length < 3) throw new Fail('expected route <prefix> <policy>...')
        if (!NAME.test(f[1])) throw new Fail(`invalid route prefix ${f[1]}`)
        if (routes.has(f[1])) throw new Fail(`prefix ${f[1]} is routed twice`)
        const list = f.slice(2).map((x) => {
          if (!policies.has(x)) throw new Fail(`unknown policy ${x}`)
          return policies.get(x)
        })
        routes.set(f[1], list)
      } else {
        if (f.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = int('tick', f[1], 0)
        if (!NAME.test(f[2])) throw new Fail(`invalid key ${f[2]}`)
        if (prev !== null && tick < prev) throw new Fail(`tick ${tick} is before tick ${prev}`)
        started = true
        prev = tick
        const key = f[2]
        let best = null
        for (const [pre, list] of routes) {
          if (key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
        }
        let denier = null
        if (best !== null) {
          const list = routes.get(best)
          for (const p of list) p.advance(key, tick)
          for (const p of list) if (!p.allows(key)) { denier = p; break }
          if (!denier) for (const p of list) p.record(key, tick)
        }
        let st = stats.get(key)
        if (!st) { st = { a: 0, d: 0 }; stats.set(key, st) }
        if (denier) st.d++; else st.a++
        out.push(denier ? `${tick} ${key} deny ${denier.name}` : `${tick} ${key} allow`)
      }
    } catch (e) {
      if (e instanceof Fail) {
        process.stderr.write(`error: line ${n + 1}: ${e.message}\n`)
        process.exit(2)
      }
      throw e
    }
  }
  if (mode === 'replay') return out.map((l) => l + '\n').join('')
  let a = 0, d = 0, s = ''
  for (const k of [...stats.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) {
    const t = stats.get(k)
    a += t.a; d += t.d
    s += `${k} allowed=${t.a} denied=${t.d}\n`
  }
  return s + `total allowed=${a} denied=${d}\n`
}

process.stdout.write(run(readFileSync(0, 'utf8')))
