import { readFileSync } from 'node:fs'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']
const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = '+-*/%=<>!(){}[],;.'

class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
  }
}

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdent = (c) => isLetter(c) || isDigit(c) || c === '_'
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'

function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  let i = 0
  let line = 1
  let col = 1
  const tokens = []

  const adv = () => {
    const c = cs[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }
  const advN = (k) => { for (let j = 0; j < k; j++) adv() }

  // consume a digit run with single underscores between digits
  const run = (pred) => {
    let s = ''
    while (i < n) {
      if (pred(cs[i])) s += adv()
      else if (cs[i] === '_' && s !== '' && pred(cs[i - 1]) && pred(cs[i + 1])) s += adv()
      else break
    }
    return s
  }

  while (i < n) {
    const c = cs[i]
    const sl = line, sc = col
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      let depth = 0
      while (i < n) {
        if (cs[i] === '/' && cs[i + 1] === '*') { depth++; advN(2) }
        else if (cs[i] === '*' && cs[i + 1] === '/') { depth--; advN(2); if (depth === 0) break }
        else adv()
      }
      if (depth > 0) throw new ScanError(sl, sc, 'unterminated block comment')
      continue
    }
    if (c === 'r' && cs[i + 1] === '"') {
      advN(2)
      let s = ''
      while (i < n && cs[i] !== '"') s += adv()
      if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
      adv()
      tokens.push([sl, sc, 'rawstring', JSON.stringify(s)])
      continue
    }
    if (isLetter(c) || c === '_') {
      let s = ''
      while (i < n && isIdent(cs[i])) s += adv()
      tokens.push([sl, sc, KEYWORDS.has(s) ? 'keyword' : 'ident', s])
      continue
    }
    if (isDigit(c)) {
      let s = ''
      const p = (cs[i + 1] || '').toLowerCase()
      const pred = c === '0' && p === 'x' ? isHex : c === '0' && p === 'b' ? isBin : c === '0' && p === 'o' ? isOct : null
      let bad = false
      if (pred) {
        s += adv(); s += adv()
        const d = run(pred)
        if (d === '') bad = true
        s += d
      } else {
        s += run(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) {
          s += adv()
          s += run(isDigit)
        }
        if (cs[i] === 'e' || cs[i] === 'E') {
          const a = cs[i + 1]
          if (isDigit(a) || ((a === '+' || a === '-') && isDigit(cs[i + 2]))) {
            s += adv()
            if (!isDigit(cs[i])) s += adv()
            s += run(isDigit)
          }
        }
      }
      if (bad || isIdent(cs[i])) {
        while (i < n && isIdent(cs[i])) s += adv()
        throw new ScanError(sl, sc, 'invalid number ' + s)
      }
      tokens.push([sl, sc, 'number', s])
      continue
    }
    if (c === '"') {
      adv()
      let v = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const ch = cs[i]
        if (ch === '"') { adv(); break }
        if (ch === '\n') throw new ScanError(line, col, 'newline in string')
        if (ch !== '\\') { v += adv(); continue }
        const bl = line, bc = col
        adv()
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const e = cs[i]
        const invalid = () => new ScanError(bl, bc, 'invalid escape \\' + e)
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', '0': '\0' }
        if (Object.hasOwn(simple, e)) { adv(); v += simple[e] }
