export class UriError extends Error {}

export function parse(s) {
  let rest = s
  const u = {}
  const m = /^([^:/?#]+):/.exec(rest)
  if (m) { u.scheme = m[1]; rest = rest.slice(m[0].length) }
  const h = rest.indexOf('#')
  if (h >= 0) { u.fragment = rest.slice(h + 1); rest = rest.slice(0, h) }
  const q = rest.indexOf('?')
  if (q >= 0) { u.query = rest.slice(q + 1); rest = rest.slice(0, q) }
  if (rest.startsWith('//')) {
    const m2 = /^\/\/[^/]*/.exec(rest)
    const auth = m2[0].slice(2)
    rest = rest.slice(m2[0].length)
    const at = auth.lastIndexOf('@')
    let hp = auth
    if (at >= 0) { u.userinfo = auth.slice(0, at); hp = auth.slice(at + 1) }
    const colon = hp.indexOf(':', hp.lastIndexOf(']') + 1)
    if (colon >= 0) { u.port = hp.slice(colon + 1); hp = hp.slice(0, colon) }
    u.host = hp
  }
  u.path = rest
  return u
}

export function removeDots(path) {
  let input = path
  const out = []
  while (input.length) {
    if (input.startsWith('../')) input = input.slice(3)
    else if (input.startsWith('./')) input = input.slice(2)
    else if (input.startsWith('/./')) input = input.slice(2)
    else if (input === '/.') input = '/'
