  }
  r.path = removeDots(r.path)
  if (r.host !== undefined && r.path === '') r.path = '/'
  return r
}

export function format(u) {
  let s = ''
  if (u.scheme !== undefined) s += u.scheme + ':'
  if (u.host !== undefined) {
    s += '//'
    if (u.userinfo !== undefined) s += u.userinfo + '@'
    s += u.host
    if (u.port !== undefined) s += ':' + u.port
  }
  s += u.path
  if (u.query !== undefined) s += '?' + u.query
  if (u.fragment !== undefined) s += '#' + u.fragment
  return s
}

export function resolve(base, ref) {
  const t = {}
  if (ref.scheme !== undefined) {
    Object.assign(t, ref)
    t.path = removeDots(ref.path)
    return t
  }
  t.scheme = base.scheme
  const setAuth = (a) => { for (const k of ['userinfo', 'host', 'port']) if (a[k] !== undefined) t[k] = a[k] }
