if (mode === 'values') {
  const values = evaluateAll(cells)
  for (const c of cells) out += `${c.key}=${formatValue(values.get(c.key))}\n`
} else {
  for (const c of cells) {
    let line = `${c.key}:`
    if (c.content.startsWith('=')) {
      const ast = parseFormula(c.content.slice(1))
      if (ast) for (const d of collectDeps(ast)) line += ` ${d}`
    }
    out += line + '\n'
  }
}
