/** Formula tokenizer, parser and dependency collection. */
import { parseAddress, keyOf } from './sheet.js'

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ t: 'num', v: m[0] }); i += m[0].length; continue
    }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ t: 'word', v: m[0] }); i += m[0].length; continue
    }
    if (s.startsWith('<>', i) || s.startsWith('<=', i) || s.startsWith('>=', i)) {
      toks.push({ t: 'op', v: s.slice(i, i + 2) }); i += 2; continue
    }
    if ('^*/+-=<>():,'.includes(c)) { toks.push({ t: 'op', v: c }); i++; continue }
    return null
  }
  return toks
}

/** Returns an AST, or null when the grammar rejects the body. */
export function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  const peek = () => toks[p]
  const isOp = (v) => p < toks.length && toks[p].t === 'op' && toks[p].v === v
  const fail = () => { throw FAIL }
  const FAIL = new Error('grammar')

  function comparison() {
    let l = additive()
    while (p < toks.length && toks[p].t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: additive() }
    }
    return l
  }
  function additive() {
    let l = multiplicative()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: multiplicative() }
    }
    return l
  }
  function multiplicative() {
    let l = power()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: power() }
    }
    return l
  }
  function power() {
    const l = unary()
    if (isOp('^')) { p++; return { k: 'bin', op: '^', l, r: power() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { k: 'unary', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    const t = peek()
    if (!t) fail()
    if (t.t === 'num') { p++; return { k: 'num', v: Number(t.v) } }
    if (t.t === 'op') {
      if (t.v === '(') {
        p++
        const e = comparison()
        if (!isOp(')')) fail()
        p++
        return { k: 'paren', e }
      }
      fail()
    }
    p++
    if (isOp('(')) {
      p++
      const args = []
      if (isOp(')')) { p++ } else {
        for (;;) {
          args.push(comparison())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          fail()
        }
      }
      return { k: 'call', name: t.v.toUpperCase(), args }
    }
    if (isOp(':')) {
      p++
      const t2 = peek()
      if (!t2 || t2.t !== 'word') fail()
      p++
      return { k: 'range', a: t.v, b: t2.v }
    }
    const u = t.v.toUpperCase()
    if (u === 'TRUE' || u === 'FALSE') return { k: 'bool', v: u === 'TRUE' }
    return { k: 'ref', w: t.v }
  }

  try {
    const e = comparison()
    if (p !== toks.length) return null
    return e
  } catch (e) {
    if (e === FAIL || e.message === 'grammar') return null
    throw e
  }
}

export function rangeCells(a, b) {
  const x = parseAddress(a)
  const y = parseAddress(b)
  if (!x || !y) return null
