/** Sheet text parsing and address helpers. */

export function parseAddress(word) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(word)
  if (!m) return null
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  const letters = m[1].toUpperCase()
  const col = letters.length === 1
    ? letters.charCodeAt(0) - 64
    : (letters.charCodeAt(0) - 64) * 26 + letters.charCodeAt(1) - 64
  return { col, row, key: letters + row }
}

export function keyOf(col, row) {
  const letters = col <= 26
    ? String.fromCharCode(64 + col)
    : String.fromCharCode(64 + Math.floor((col - 1) / 26)) + String.fromCharCode(65 + ((col - 1) % 26))
  return letters + row
}

export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const seen = new Map()
  lines.forEach((raw, i) => {
    const line = raw.replace(/^[ \t]+/, '')
    if (line === '' || line[0] === '#') return
    const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(line)
    const word = m[1]
    const addr = parseAddress(word)
    if (!addr) throw sheetError(`error: line ${i + 1}: invalid cell address ${word}`)
    if (seen.has(addr.key)) throw sheetError(`error: line ${i + 1}: cell ${word} is declared twice`)
    seen.set(addr.key, { key: addr.key, col: addr.col, row: addr.row, content: m[2] })
  })
  return [...seen.values()].sort((a, b) => a.col - b.col || a.row - b.row)
}

function sheetError(msg) {
  const e = new Error(msg)
  e.sheetError = true
  return e
}
