    }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ t: 'word', v: m[0] }); i += m[0].length; continue
    }
    if (s.startsWith('<>', i) || s.startsWith('<=', i) || s.startsWith('>=', i)) {
      toks.push({ t: 'op', v: s.slice(i, i + 2) }); i += 2; continue
