import { readFileSync } from 'node:fs'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.')
const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

class ScanError extends Error {}

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isLetter = (c) => c !== undefined && /^[A-Za-z]$/.test(c)
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdChar = (c) => isIdStart(c) || isDigit(c)

function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const tokens = []
  let i = 0, line = 1, col = 1

  const adv = (k = 1) => {
    for (let j = 0; j < k; j++) {
      const c = cs[i++]
      if (c === '\n') { line++; col = 1 }
      else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
      else col++
    }
  }
  const fail = (l, c, msg) => { throw new ScanError(`${l}:${c}: ${msg}`) }
  // position of index k, given we're currently at i (k >= i, no newlines/tabs in between assumed by caller)
  const push = (l, c, kind, body) => tokens.push({ l, c, kind, body })

  // digit run starting at j with predicate; underscores allowed between digits. returns end index
  const run = (j, pred) => {
    if (!pred(cs[j])) return j
    j++
    for (;;) {
      if (pred(cs[j])) j++
      else if (cs[j] === '_' && pred(cs[j + 1])) j += 2
      else return j
    }
  }

  while (i < n) {
    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      const sl = line, sc = col
      let depth = 0
      for (;;) {
        if (i >= n) fail(sl, sc, 'unterminated block comment')
        if (cs[i] === '/' && cs[i + 1] === '*') { depth++; adv(2) }
        else if (cs[i] === '*' && cs[i + 1] === '/') { depth--; adv(2); if (depth === 0) break }
        else adv()
      }
      continue
    }
    const sl = line, sc = col
    if (c === 'r' && cs[i + 1] === '"') {
      let j = i + 2
      while (j < n && cs[j] !== '"') j++
      if (j >= n) fail(sl, sc, 'unterminated string')
      const val = cs.slice(i + 2, j).join('')
      adv(j + 1 - i)
      push(sl, sc, 'rawstring', JSON.stringify(val))
      continue
    }
    if (isIdStart(c)) {
      let j = i + 1
      while (isIdChar(cs[j])) j++
      const w = cs.slice(i, j).join('')
      adv(j - i)
      push(sl, sc, KEYWORDS.has(w) ? 'keyword' : 'ident', w)
      continue
    }
    if (isDigit(c)) {
      let j = i + 1
      let bad = false
      const p = cs[i + 1]
      const pre = c === '0' && p !== undefined ? p.toLowerCase() : ''
      if (pre === 'x' || pre === 'b' || pre === 'o') {
        const pred = pre === 'x' ? isHex : pre === 'b' ? (d) => d === '0' || d === '1' : (d) => d !== undefined && d >= '0' && d <= '7'
        j = i + 2
        const e = run(j, pred)
        if (e === j) bad = true
        j = e
      } else {
        j = run(i, isDigit)
        if (cs[j] === '.' && isDigit(cs[j + 1])) j = run(j + 1, isDigit)
        if (cs[j] === 'e' || cs[j] === 'E') {
          if (isDigit(cs[j + 1])) j = run(j + 1, isDigit)
          else if ((cs[j + 1] === '+' || cs[j + 1] === '-') && isDigit(cs[j + 2])) j = run(j + 2, isDigit)
        }
      }
      if (isIdChar(cs[j])) bad = true
      if (bad) {
        while (isIdChar(cs[j])) j++
        fail(sl, sc, `invalid number ${cs.slice(i, j).join('')}`)
      }
      const w = cs.slice(i, j).join('')
      adv(j - i)
      push(sl, sc, 'number', w)
      continue
    }
    if (c === '"') {
      let out = ''
      let j = i + 1
      // track position while scanning
      let l = line, cc = col + 1
      for (;;) {
        if (j >= n) fail(sl, sc, 'unterminated string')
        const d = cs[j]
        if (d === '"') { j++; break }
        if (d === '\n') fail(l, cc, 'newline in string')
        if (d === '\\') {
          const bl = l, bc = cc
          const e = cs[j + 1]
          if (e === undefined) fail(sl, sc, 'unterminated string')
          const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
          if (Object.prototype.hasOwnProperty.call(simple, e)) { out += simple[e]; j += 2; cc += 2; continue }
          if (e === 'x') {
            if (isHex(cs[j + 2]) && isHex(cs[j + 3])) {
              out += String.fromCharCode(parseInt(cs[j + 2] + cs[j + 3], 16))
              j += 4; cc += 4; continue
            }
            fail(bl, bc, 'invalid escape \\x')
          }
          if (e === 'u' && cs[j + 2] === '{') {
            let k = j + 3
            while (isHex(cs[k])) k++
            if (k > j + 3 && cs[k] === '}') {
              const v = parseInt(cs.slice(j + 3, k).join(''), 16)
              if (v <= 0x10ffff) {
                out += String.fromCodePoint(v)
                cc += k + 1 - j; j = k + 1; continue
              }
            }
            fail(bl, bc, 'invalid escape \\u')
          }
          fail(bl, bc, `invalid escape \\${e}`)
        }
        out += d
        j++
        if (d === '\t') cc = Math.floor((cc - 1) / 4) * 4 + 5
        else cc++
      }
      adv(j - i)
      push(sl, sc, 'string', JSON.stringify(out))
      continue
    }
    const two = c + (cs[i + 1] ?? '')
    if (PUNCT2.includes(two)) { adv(2); push(sl, sc, 'punct', two); continue }
    if (PUNCT1.has(c)) { adv(); push(sl, sc, 'punct', c); continue }
    fail(sl, sc, `unexpected character ${c}`)
  }
  return tokens
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }
  const text = readFileSync(0).toString('utf8')
  let tokens
  try {
    tokens = scan(text)
  } catch (e) {
    if (!(e instanceof ScanError)) throw e
    process.stderr.write(`error: ${e.message}\n`)
    process.exit(2)
  }
  let out = ''
  if (args[0] === 'tokens') {
    for (const t of tokens) out += `${t.l}:${t.c} ${t.kind} ${t.body}\n`
  } else {
    for (const k of KINDS) out += `${k} ${tokens.filter((t) => t.kind === k).length}\n`
    out += `total ${tokens.length}\n`
  }
  process.stdout.write(out)
}

main()
