  if (c === "'") return parseLiteral(cur)
  if (!isBare(c)) fail('expected a name')
  const start = cur.i
  while (isBare(cur.c)) cur.i++
  return cur.s.slice(start, cur.i)
}

function parseBasic(cur) {
  cur.i++
  let out = ''
  for (;;) {
    const c = cur.c
    if (c === undefined) fail('unterminated string')
    cur.i++
    if (c === '"') return out
    if (c !== '\\') {
      out += c
      continue
    }
    const e = cur.c
    if (e === undefined) fail('unterminated string')
    cur.i++
    const simple = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
    if (Object.hasOwn(simple, e)) out += simple[e]
    else if (e === 'u') {
      const hex = cur.s.slice(cur.i, cur.i + 4)
      if (!/^[0-9A-Fa-f]{4}$/.test(hex)) fail('invalid escape \\u')
      out += String.fromCharCode(parseInt(hex, 16))
      cur.i += 4
    } else {
      // a full code point, so a surrogate pair is reported whole
      const cp = String.fromCodePoint(cur.s.codePointAt(cur.i - 1))
      fail(`invalid escape \\${cp}`)
    }
  }
}

function parseLiteral(cur) {
  const end = cur.s.indexOf("'", cur.i + 1)
  if (end < 0) fail('unterminated string')
  const v = cur.s.slice(cur.i + 1, end)
  cur.i = end + 1
  return v
}

function parseValue(cur, path) {
  const c = cur.c
  if (cur.atEnd() || c === ',' || c === ']' || c === '}') fail('expected a value')
  if (c === '"') return { t: 'string', v: parseBasic(cur) }
  if (c === "'") return { t: 'string', v: parseLiteral(cur) }
  if (c === '[') return parseArray(cur, path)
  if (c === '{') return parseInline(cur, path)
  const start = cur.i
  while (cur.c !== undefined && !isWs(cur.c) && cur.c !== ',' && cur.c !== ']' && cur.c !== '}') cur.i++
  const tok = cur.s.slice(start, cur.i)
  if (tok === 'true' || tok === 'false') return { t: 'boolean', v: tok === 'true' }
  const D = '\\d+(?:_\\d+)*'
  if (new RegExp(`^[+-]?${D}$`).test(tok)) {
    return { t: 'integer', v: BigInt(tok.replace(/_/g, '')).toString() }
  }
  if (new RegExp(`^[+-]?${D}(?:\\.${D}(?:[eE][+-]?${D})?|[eE][+-]?${D})$`).test(tok)) {
    return { t: 'float', v: Number(tok.replace(/_/g, '')) }
  }
  fail(`invalid value ${tok}`)
}

function parseArray(cur, path) {
  cur.i++
  const items = []
  for (;;) {
    cur.ws()
    if (cur.atEnd()) fail('unterminated array')
    if (cur.c === ']') {
      cur.i++
      return { t: 'array', items, tables: false }
    }
    items.push(parseValue(cur, path))
    cur.ws()
    if (cur.c === ',') cur.i++
    else if (cur.c === ']') {
      cur.i++
      return { t: 'array', items, tables: false }
    } else fail('unterminated array')
  }
}

function parseInline(cur, path) {
  cur.i++
  const table = newTable()
  cur.ws()
  if (cur.atEnd()) fail('unterminated inline table')
  if (cur.c === '}') {
    cur.i++
    return table
  }
  for (;;) {
    cur.ws()
    if (cur.atEnd()) fail('unterminated inline table')
    const { parts } = parseDotted(cur)
    cur.ws()
    if (cur.c !== '=') fail('expected = in an inline table')
    cur.i++
    cur.ws()
    const value = parseValue(cur, [...path, ...parts])
    assign(table, parts, value, path)
    cur.ws()
    if (cur.c === ',') cur.i++
    else if (cur.c === '}') {
      cur.i++
      return table
    } else fail('unterminated inline table')
  }
}
